WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM sessions), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, device, COUNT(CASE WHEN country = 'UK' THEN 1 END) AS uk_count, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, SIZE(COLLECT_SET(device)) AS num_devices, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('WEEK', started_at) ORDER BY COUNT(CASE WHEN country = 'UK' THEN 1 END) DESC) AS uk_count_percent_rank FROM sessionized GROUP BY 1, 2 HAVING num_devices < 1000 ORDER BY week_start DESC
